  for (const accountIdHash of accountIdHashes) {
    const key = codexResetUsageKey(accountIdHash);
    const entry = await kv.get(key, { consistency: "strong" });
    if (entry.value === null) atomic = atomic.check(entry).set(key, { enabled: false });
