import json, glob, os, collections

FILES = sorted(glob.glob('/Users/nv/.codex/sessions/2026/10/*/*.jsonl'))

def load(f):
    meta=None; tcs=[]; items=[]; usages=[]
    with open(f) as fh:
        for line in fh:
            line=line.strip()
            if not line: continue
            try: o=json.loads(line)
            except Exception: continue
            t=o.get('type'); p=o.get('payload',{}) or {}; ordv=o.get('ordinal')
            if t=='session_meta': meta=p
            elif t=='turn_context': tcs.append((ordv,p))
            elif t=='response_item': items.append((ordv,p))
            elif t=='token_usage_record': usages.append((ordv,'tur',p))
            elif t=='event_msg' and p.get('type')=='token_count': usages.append((ordv,'tc',p))
    return meta,tcs,items,usages

def candidate(meta):
    ts=meta.get('thread_source'); src=meta.get('source')
    sub=(ts=='subagent') or (isinstance(src,dict) and 'subagent' in src)
    if not sub: return False
    return True

def model_ok(m):
    m=m or ''
    return m.startswith('deepseek-ai/DeepSeek-V4.1-Flash') or m=='deepseek-flash' or m.startswith('deepseek-v4-flash')

def is_assistant_side(p):
    t=p.get('type')
    if t=='message': return p.get('role')=='assistant'
    return t in ('function_call','custom_tool_call','reasoning')

def is_boundary_item(p):
    t=p.get('type')
    if t=='message': return p.get('role') in ('user','developer')
    if t=='agent_message': return True
    return t in ('function_call_output','custom_tool_call_output')

CLASSES=[('small',2000,10000),('medium',10000,40000),('large',40000,160000),('xlarge',160000,600000)]
def cls_of(n):
    for name,lo,hi in CLASSES:
        if lo<=n<=hi: return name
    return None

report=[]
for f in FILES:
    meta,tcs,items,usages=load(f)
    if not meta or not candidate(meta): continue
    ms=[p.get('model') for _,p in tcs if model_ok(p.get('model'))]
    if not ms: continue
    # boundaries
    bounds=[]
    for i in range(len(items)-1):
        p=items[i][1]
        if is_boundary_item(p) and is_assistant_side(items[i+1][1]):
            # enforce call-before-output
            t=p.get('type')
            ok=True
            if t in ('function_call_output','custom_tool_call_output'):
                cid=p.get('call_id')
                found=any(q.get('call_id')==cid for _,q in items[:i])
                ok=found
            if ok: bounds.append(i)
    # usage picker: nearest usage at/after boundary (in ordinal order)
    def usage_for(i):
        ordb=items[i][0]
        for o,kind,p in usages:
            if o is not None and ordb is not None and o>=ordb:
                if kind=='tur':
                    u=p.get('turn_token_usage') or p.get('usage') or {}
                else:
                    u=(p.get('info') or {}).get('last_token_usage') or (p.get('info') or {}).get('total_token_usage') or {}
                return u.get('input_tokens'), ('tur' if kind=='tur' else 'tc')
        return None,None
    rows=[]
    for i in bounds:
        n,src=usage_for(i)
        rows.append((i,n,src,items[i][1].get('type'),items[i][1].get('role'),cls_of(n) if n else None))
    print(os.path.basename(f))
    print('   cwd:',meta.get('cwd'),'| originator:',meta.get('originator'),'| model:',sorted(set(ms)))
    for i,n,src,t,role,c in rows:
        tid=(items[i][1].get('internal_chat_message_metadata_passthrough') or {}).get('turn_id')
        # find effort for that turn
        eff=None
        for _,p in tcs:
            if tid and p.get('turn_id')==tid: eff=p.get('effort')
        print(f'   b@{i} {t}/{role} tokens={n} src={src} class={c} turn={tid} effort={eff}')
EOF
