    settlement_request_id: settlementRequestId,
    provider_quota: providerQuota,
    input_tokens: usage.input_tokens,
    cached_input_tokens: cachedInputTokens,
    output_tokens: usage.output_tokens,
    model,
    created_at_ms: Date.now(),
